arduino-uno.source:
class Counter {
 public:
  explicit Counter(int start) : n(start) {}
  int next() { return n++; }
 private:
  int n;
};
Counter counter(20);
String label = "n";

void setup() {
  Serial.begin(9600);
  Serial.println(F("hello from C++"));
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  report(counter.next());
  digitalWrite(LED_BUILTIN, !digitalRead(LED_BUILTIN));
  delay(100);
}

void report(int v) {
  Serial.println(label + "=" + String(v) + " pi=" + String(3.14159, 3));
}

